import {
  check,
  index,
  integer,
  pgTable,
  text,
  timestamp,
  uuid,
  varchar,
} from 'drizzle-orm/pg-core';
import { sql } from 'drizzle-orm';

export const USER_ROLES = ['learner', 'reviewer', 'admin'] as const;
export const USER_STATUSES = ['active', 'blocked'] as const;
export const ONBOARDING_OUTCOMES = ['completed', 'skipped'] as const;

/**
 * Accounts (data-model.md §4). `id` is generated by the application and equals `Learner.id` in the graph.
 * No password, username, or identity-provider column: sign-in is Cognito's; identities live in `user_identities`.
 */
export const users = pgTable(
  'users',
  {
    id: uuid('id').primaryKey(),
    /** Stored trimmed and lower-case. The only place an e-mail address is kept. */
    email: varchar('email', { length: 254 }).notNull().unique(),
    displayName: varchar('display_name', { length: 120 }).notNull(),
    role: text('role', { enum: USER_ROLES }).notNull().default('learner'),
    status: text('status', { enum: USER_STATUSES }).notNull().default('active'),
    /** Extra puzzle creations from access codes or the admin, consumed after the monthly allowance (data-model.md §4). */
    bonusSourceRuns: integer('bonus_source_runs').notNull().default(0),
    bonusPromptRuns: integer('bonus_prompt_runs').notNull().default(0),
    /** The hourly creation limit is lifted while this is in the future. */
    limitsLiftedUntil: timestamp('limits_lifted_until', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    /** Null = never signed in. */
    lastSeenAt: timestamp('last_seen_at', { withTimezone: true }),
    /** When the user completed or skipped the first-run carousel (spec 009). Null = not yet. Set once with the outcome. */
    onboardedAt: timestamp('onboarded_at', { withTimezone: true }),
    onboardingOutcome: text('onboarding_outcome', { enum: ONBOARDING_OUTCOMES }),
  },
  (table) => [
    check('users_role_check', sql`${table.role} in ('learner', 'reviewer', 'admin')`),
    check('users_status_check', sql`${table.status} in ('active', 'blocked')`),
    check(
      'users_onboarding_outcome_check',
      sql`${table.onboardingOutcome} in ('completed', 'skipped')`,
    ),
    check('users_bonus_source_runs_check', sql`${table.bonusSourceRuns} >= 0`),
    check('users_bonus_prompt_runs_check', sql`${table.bonusPromptRuns} >= 0`),
  ],
);

/** One account can have several identities (Google, and an e-mail-and-password identity with the same address). Never leaves the accounts module. */
export const userIdentities = pgTable(
  'user_identities',
  {
    /** The identity provider's subject id. */
    cognitoSub: text('cognito_sub').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    /** 'google' | 'cognito' */
    provider: text('provider').notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [index('user_identities_user_id').on(table.userId)],
);

export type UserRow = typeof users.$inferSelect;
export type NewUserRow = typeof users.$inferInsert;
